package got.wildlife; import net.minecraft.world.entity.EntityType; import net.minecraft.world.level.Level; public final class GOTRedScorpionEntity extends GOTScorpionEntity { public GOTRedScorpionEntity(EntityType<? extends GOTRedScorpionEntity> t, Level l){super((EntityType)t,l,Species.RED);} public static net.minecraft.world.entity.ai.attributes.AttributeSupplier.Builder createRedAttributes(){return GOTScorpionEntity.createAttributes().add(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH,24).add(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE,5);} }
